WITH exploded AS (SELECT id, plan, effective_from, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) t AS tier_value), filtered AS (SELECT *, CASE WHEN plan = 'basic' THEN 1 ELSE 0 END AS is_basic, SUBSTRING(plan, 1, 2) AS plan_prefix FROM exploded WHERE tier_value <= 58), base AS (SELECT *, GREATEST(is_basic, tier_value) AS greatest_is_basic_tier_value FROM filtered WHERE effective_from >= DATE '2024-06-04' AND is_basic > 77), filtered_price_tiers AS (SELECT id, plan, effective_from, tier_value, plan_prefix, greatest_is_basic_tier_value, LENGTH(plan) AS plan_length, LEAST(is_basic, greatest_is_basic_tier_value) AS least_is_basic_greatest_is_basic_tier_value FROM base WHERE plan = 'pro'), scored AS (SELECT id, effective_from, tier_value, plan_prefix, greatest_is_basic_tier_value, plan_length, RANK() OVER w_ordered AS tier_value_rank, MAX(tier_value) OVER (PARTITION BY plan) AS plan_max_tier_value, DENSE_RANK() OVER w_recent AS plan_length_dense_rank FROM filtered_price_tiers WHERE plan = 'basic' WINDOW w_ordered AS (ORDER BY tier_value NULLS LAST), w_recent AS (PARTITION BY plan ORDER BY plan_length)), valid AS (SELECT *, tier_value * greatest_is_basic_tier_value AS tier_value_times_greatest_is_basic_tier_value FROM scored WHERE effective_from >= TO_DATE('2024-04-15')) SELECT tier_value, plan_length, plan_max_tier_value, tier_value_times_greatest_is_basic_tier_value, CUME_DIST() OVER (ORDER BY tier_value) AS tier_value_cume_dist, DENSE_RANK() OVER (ORDER BY plan_length_dense_rank) AS plan_length_dense_rank_dense_rank, CUME_DIST() OVER (ORDER BY tier_value NULLS FIRST) AS tier_value_cume_dist_2 FROM valid;
